/**
 * Brand autopilot — the rules for AI-drafted posts for NowOpen Africa's OWN
 * accounts.
 *
 * This is the drafting half only. A model writes a post from a brief; the
 * result lands in brand_social_content as a DRAFT, and from there it takes
 * exactly the path a hand-written post takes: checks, review, a person's
 * approval, then Zoho. Nothing in this file can approve or send anything.
 *
 * Pure functions with no imports, so the admin screen and the edge function
 * (brand-social-generate) share one copy and every rule is pinned by a test.
 * The edge copy is generated by `npm run sync:brand-social`.
 *
 * Two things a model will do unless stopped, and this file stops both:
 *   * Invent facts. The prompt forbids numbers, partners, prices, quotes and
 *     named businesses, and tells the model to write a [bracket] placeholder
 *     where a fact is needed. The existing checker blocks any post that still
 *     contains a placeholder, so an unverified fact cannot be sent.
 *   * Return something that is not the shape asked for. `parseGeneration`
 *     accepts only the exact fields it knows, for only the channels requested,
 *     and reports what was wrong instead of guessing.
 */

export interface AutopilotBrief {
  /** Pillar id from the brand profile. */
  pillar: string;
  /** Audience id from the brand profile. */
  audience: string;
  /** Objective from the brand profile's list. */
  objective: string;
  /** What the post is about, in the founder's words. */
  topic: string;
  /** Channel ids the post is for. */
  channels: string[];
  format?: 'text' | 'image' | 'carousel' | 'video';
  tone?: string;
  /** Call to action. Defaults to the profile's main one. */
  cta?: string;
  /** Link the post should send people to. */
  destinationUrl?: string;
  /** UTC instant the post is planned for, or null to leave it unscheduled. */
  plannedAt?: string | null;
  campaignId?: string | null;
}

export interface AutopilotProfile {
  positioning?: string;
  products?: Record<string, string>;
  lines?: string[];
  main_cta?: string;
  pillars: { id: string; label: string; purpose?: string }[];
  audiences: { id: string; label: string }[];
  objectives: string[];
  honesty_rules?: string[];
}

export interface AutopilotChannel { id: string; label: string; maxChars: number; requires?: string; linkNotClickable?: boolean }

export const FORMATS = ['text', 'image', 'carousel', 'video'] as const;
export const MAX_TOPIC_CHARS = 400;
/** One request writes for at most this many channels, to keep the answer inside the token ceiling. */
export const MAX_CHANNELS_PER_BRIEF = 6;
/** Upper bound on the model's answer for one post. */
export const GENERATION_MAX_TOKENS = 2400;

// ── Brief ────────────────────────────────────────────────────────────────────

/** Problems with a brief, in plain words. Empty means it can be sent to the model. */
export function validateBrief(b: AutopilotBrief, profile: AutopilotProfile, channelIds: string[]): string[] {
  const out: string[] = [];
  if (!profile.pillars.some((p) => p.id === b.pillar)) out.push('Choose a content pillar.');
  if (!profile.audiences.some((a) => a.id === b.audience)) out.push('Choose an audience.');
  if (!profile.objectives.includes(b.objective)) out.push('Choose an objective.');
  const topic = (b.topic ?? '').trim();
  if (topic.length < 8) out.push('Say what the post is about (at least a few words).');
  if (topic.length > MAX_TOPIC_CHARS) out.push(`Keep the topic under ${MAX_TOPIC_CHARS} characters.`);
  if (!b.channels?.length) out.push('Choose at least one channel.');
  if ((b.channels?.length ?? 0) > MAX_CHANNELS_PER_BRIEF) out.push(`Choose at most ${MAX_CHANNELS_PER_BRIEF} channels per post.`);
  const unknown = (b.channels ?? []).filter((c) => !channelIds.includes(c));
  if (unknown.length) out.push(`These channels are not active: ${unknown.join(', ')}.`);
  if (new Set(b.channels ?? []).size !== (b.channels ?? []).length) out.push('A channel is listed twice.');
  if (b.format && !(FORMATS as readonly string[]).includes(b.format)) out.push('Unknown format.');
  if (b.plannedAt && Number.isNaN(new Date(b.plannedAt).getTime())) out.push('The planned time is not a valid date.');
  return out;
}

// ── Prompts ──────────────────────────────────────────────────────────────────

export function buildSystemPrompt(profile: AutopilotProfile): string {
  const products = Object.entries(profile.products ?? {}).map(([k, v]) => `- ${k}: ${v}`).join('\n');
  return [
    'You write social media posts for NowOpen Africa\'s own official accounts.',
    '',
    `Positioning: ${profile.positioning ?? ''}`,
    products ? `What the platform does:\n${products}` : '',
    profile.lines?.length ? `Approved brand lines (use at most one, exactly as written):\n${profile.lines.map((l) => `- ${l}`).join('\n')}` : '',
    `Main call to action: "${profile.main_cta ?? 'Add your business'}". Never write "List your business".`,
    '',
    'RULES YOU MUST NOT BREAK:',
    '- State no numbers of users, businesses, followers, cities or countries, and no percentages.',
    '- Make no claims about how many people do something: no "most customers", "the majority of", "millions of", "everyone". Speak about the reader instead ("your customers", "people near you").',
    '- Name no partners, backers, awards or endorsements.',
    '- Mention no prices, discounts or guarantees.',
    '- Write no testimonials and no quotations from any person.',
    '- Name no real business or person. If the post needs a specific fact, name or date, write it as a [bracket placeholder] such as [business name]. A person fills it in before it is sent.',
    '- Do not describe a feature unless it appears in "What the platform does" above.',
    '- Do not say anything launches, is new or is "now live".',
    '- No "first", "biggest", "leading", "#1" or "only" claims.',
    ...(profile.honesty_rules ?? []).map((r) => `- ${r}`),
    '',
    'STYLE: plain, warm, direct English. Short sentences. No hype words. Write for the named audience. Each channel gets its own version: different length, opening and structure, not the same text pasted.',
    '',
    'Answer with ONE JSON object and nothing else. No code fence, no commentary.',
  ].filter((l) => l !== '').join('\n');
}

export function buildUserPrompt(
  brief: AutopilotBrief,
  profile: AutopilotProfile,
  channels: AutopilotChannel[],
  recentCaptions: string[],
): string {
  const pillar = profile.pillars.find((p) => p.id === brief.pillar);
  const audience = profile.audiences.find((a) => a.id === brief.audience);
  const lines = [
    `Topic: ${brief.topic.trim()}`,
    `Content pillar: ${pillar?.label ?? brief.pillar}${pillar?.purpose ? ` (${pillar.purpose})` : ''}`,
    `Audience: ${audience?.label ?? brief.audience}`,
    `Objective: ${brief.objective}`,
    `Format: ${brief.format ?? 'text'}`,
    `Tone: ${brief.tone?.trim() || 'the brand\'s usual plain, warm voice'}`,
    `Call to action: ${brief.cta?.trim() || profile.main_cta || 'Add your business'}`,
    brief.destinationUrl ? `Link: ${brief.destinationUrl} (do not paste it into captions for channels where links are not clickable; say "link in bio")` : 'No link.',
    '',
    'Write for these channels:',
    ...channels.map((c) => `- "${c.id}" (${c.label}): at most ${c.maxChars} characters${c.linkNotClickable ? '; links are not clickable' : ''}${c.requires ? `; needs ${c.requires.replace(/_/g, ' ')} (describe it in creative_brief)` : ''}`),
    '',
  ];
  if (recentCaptions.length) {
    lines.push('Recent posts. Do NOT repeat their angle, opening or wording:');
    for (const c of recentCaptions.slice(0, 25)) lines.push(`- ${c.replace(/\s+/g, ' ').slice(0, 160)}`);
    lines.push('');
  }
  lines.push(
    'JSON shape:',
    '{',
    '  "hook": "the first line, under 90 characters",',
    '  "caption": "the master caption",',
    '  "creative_brief": "what the image, carousel or video should show, for a designer. No generated faces of real people.",',
    '  "cta": "the call to action used",',
    `  "variants": { ${channels.map((c) => `"${c.id}": "caption for ${c.label}"`).join(', ')} }`,
    '}',
  );
  return lines.join('\n');
}

// ── Reading the answer ───────────────────────────────────────────────────────

export interface GeneratedPost {
  hook: string;
  caption: string;
  creativeBrief: string;
  cta: string;
  variants: Record<string, string>;
}

export type ParseResult = { ok: true; post: GeneratedPost } | { ok: false; errors: string[] };

/** The first balanced {...} in a string, ignoring braces inside JSON strings. */
function firstJsonObject(text: string): string | null {
  const start = text.indexOf('{');
  if (start < 0) return null;
  let depth = 0; let inString = false; let escaped = false;
  for (let i = start; i < text.length; i++) {
    const ch = text[i];
    if (inString) {
      if (escaped) escaped = false;
      else if (ch === '\\') escaped = true;
      else if (ch === '"') inString = false;
      continue;
    }
    if (ch === '"') inString = true;
    else if (ch === '{') depth++;
    else if (ch === '}') { depth--; if (depth === 0) return text.slice(start, i + 1); }
  }
  return null;
}

const str = (v: unknown) => (typeof v === 'string' ? v.trim() : '');

/**
 * Turn a model's answer into a post, or say why it cannot be used.
 *
 * Strict on purpose: every requested channel must have its own non-empty
 * caption, and a channel that was not asked for is dropped rather than saved.
 * A missing channel is an error, not something to fill from the master
 * caption, because a blind copy is exactly what the variants exist to avoid.
 */
export function parseGeneration(text: string, channelIds: string[]): ParseResult {
  const raw = firstJsonObject(text ?? '');
  if (!raw) return { ok: false, errors: ['The model did not return a JSON object.'] };
  let data: Record<string, unknown>;
  try {
    data = JSON.parse(raw) as Record<string, unknown>;
  } catch {
    return { ok: false, errors: ['The model returned JSON that could not be read.'] };
  }
  const errors: string[] = [];
  const caption = str(data.caption);
  if (!caption) errors.push('The master caption is missing.');
  const rawVariants = (data.variants && typeof data.variants === 'object' && !Array.isArray(data.variants))
    ? data.variants as Record<string, unknown> : {};
  const variants: Record<string, string> = {};
  for (const id of channelIds) {
    const v = str(rawVariants[id]);
    if (!v) errors.push(`No caption came back for ${id}.`);
    else variants[id] = v;
  }
  if (errors.length) return { ok: false, errors };
  return {
    ok: true,
    post: {
      hook: str(data.hook).slice(0, 200),
      caption,
      creativeBrief: str(data.creative_brief),
      cta: str(data.cta),
      variants,
    },
  };
}

// ── Budget ───────────────────────────────────────────────────────────────────

export interface AutopilotBudget {
  enabled: boolean;
  /** Tokens (input + output) allowed per Lagos calendar month. 0 = none. */
  monthlyTokenLimit: number;
  /** Tokens providers have reported this month. */
  usedTokens: number;
}

export type BudgetVerdict = { ok: true; remaining: number } | { ok: false; reason: string };

/**
 * May one more post be generated?
 *
 * Refuses unless the founder has both switched generation on and set a
 * ceiling: "no budget configured" must mean "no calls", never "unlimited".
 * A call is refused when what is left could not cover a full answer, so the
 * ceiling is not crossed mid-call.
 */
export function budgetVerdict(b: AutopilotBudget, perCallCeiling = GENERATION_MAX_TOKENS * 2): BudgetVerdict {
  if (!b.enabled) return { ok: false, reason: 'AI drafting is switched off. Turn it on in the Autopilot settings.' };
  if (!(b.monthlyTokenLimit > 0)) return { ok: false, reason: 'No monthly AI limit is set, so nothing is generated. Set one in the Autopilot settings.' };
  const remaining = b.monthlyTokenLimit - b.usedTokens;
  if (remaining < perCallCeiling) {
    return { ok: false, reason: `This month's AI limit is used up (${b.usedTokens.toLocaleString('en-GB')} of ${b.monthlyTokenLimit.toLocaleString('en-GB')} tokens).` };
  }
  return { ok: true, remaining };
}

/** First instant of the Lagos calendar month containing `now`, as UTC ISO. Lagos is UTC+1 all year. */
export function lagosMonthStartUtc(now: Date = new Date()): string {
  const parts = new Intl.DateTimeFormat('en-CA', { timeZone: 'Africa/Lagos', year: 'numeric', month: '2-digit' }).formatToParts(now);
  const y = Number(parts.find((p) => p.type === 'year')?.value);
  const m = Number(parts.find((p) => p.type === 'month')?.value);
  return new Date(Date.UTC(y, m - 1, 1, -1, 0)).toISOString();
}

// ── A week's plan ────────────────────────────────────────────────────────────

export interface WeekSlot {
  /** Lagos calendar day, "2026-11-16". */
  day: string;
  /** Lagos wall-clock time, "08:30". */
  time: string;
  /** "2026-11-16T08:30", ready for lagosLocalToUtc. */
  local: string;
  pillar: string;
}

/** The slots the hand-built calendar already uses (Lagos time). */
export const DEFAULT_SLOT_TIMES = ['08:30', '13:00', '19:00'] as const;

/**
 * Seven days of slots from `startDay`, pillars taken in rotation so no pillar
 * runs twice in a row and each gets a fair share. Deterministic: the same
 * inputs always give the same plan, so the founder can read it before a single
 * model call is made.
 */
export function planWeek(startDay: string, pillarIds: string[], perDay = 1, times: readonly string[] = DEFAULT_SLOT_TIMES): WeekSlot[] {
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(startDay);
  if (!m || !pillarIds.length) return [];
  const n = Math.max(1, Math.min(perDay, times.length));
  const base = Date.UTC(Number(m[1]), Number(m[2]) - 1, Number(m[3]));
  const out: WeekSlot[] = [];
  let k = 0;
  for (let d = 0; d < 7; d++) {
    const day = new Date(base + d * 86_400_000).toISOString().slice(0, 10);
    for (let s = 0; s < n; s++) {
      const time = times[s];
      out.push({ day, time, local: `${day}T${time}`, pillar: pillarIds[k % pillarIds.length] });
      k++;
    }
  }
  return out;
}
